@if($cards->isEmpty())<div class="production-empty"><span>▣</span><h3>No ID production requests yet</h3><p>Create an ID request for an eligible student to begin monitoring production.</p>@if(auth()->user()->hasPermission('cards.manage'))<a class="btn primary" href="{{ route('production.create') }}">Create ID Request</a>@endif</div>@else<form method="POST" action="{{ route('production.bulk') }}" id="bulkForm">@csrf<div class="bulk-bar"><span><b id="selectedCount">0</b> selected</span><select name="status" required><option value="">Bulk action</option><option value="for_printing">Move to For Printing</option><option value="printed">Confirm Printed</option><option value="ready_for_release">Mark Ready for Release</option></select><button class="btn secondary" @disabled(!auth()->user()->hasPermission('cards.print'))>Apply</button></div><div class="table-wrap"><table class="production-table"><thead><tr><th><input type="checkbox" id="selectAll"></th><th>Student</th><th>Program / Level</th><th>Academic Term</th><th>Issuance</th><th>Status</th><th>Requested</th><th></th></tr></thead><tbody>@foreach($cards as $card)@php($enrollment=$card->academic_term_id?$card->student->enrollments->firstWhere('academic_term_id',$card->academic_term_id):$card->student->latestEnrollment)<tr><td><input type="checkbox" name="card_ids[]" value="{{ $card->id }}" class="card-select" data-status="{{ $card->status->value }}"></td><td><strong>{{ $card->student->full_name }}</strong><small class="mono">{{ $card->student->student_number }}</small></td><td>{{ $enrollment?->program?->code??'—' }}<small>{{ collect([$enrollment?->year_level,$enrollment?->section])->filter()->implode(' / ')?:'—' }}</small></td><td>{{ $card->academicTerm?->academicYear?->name??'—' }}<small>{{ $card->academicTerm?->name??$card->semester??'—' }}</small></td><td>{{ str($card->issuance_type)->title() }}</td><td><span class="production-status status-{{ $card->status->value }}">{{ str($card->status->value)->replace('_',' ')->title() }}</span></td><td>{{ $card->requested_at?->format('M j, Y')??$card->created_at->format('M j, Y') }}</td><td><a href="{{ route('production.show',$card) }}">View</a></td></tr>@endforeach</tbody></table></div></form>{{ $cards->links() }}@endif</section>
