@push('scripts')<script>(()=>{const advanced=document.getElementById('productionAdvanced');document.getElementById('productionFilterToggle')?.addEventListener('click',()=>advanced.toggleAttribute('hidden'));const boxes=[...document.querySelectorAll('.card-select')],count=document.getElementById('selectedCount');const sync=()=>{if(count)count.textContent=boxes.filter(b=>b.checked).length};boxes.forEach(b=>b.onchange=sync);document.getElementById('selectAll')?.addEventListener('change',e=>{boxes.forEach(b=>b.checked=e.target.checked);sync()});document.getElementById('bulkForm')?.addEventListener('submit',e=>{const selected=boxes.filter(b=>b.checked),target=e.currentTarget.elements.status.value,required={for_printing:'pending',printed:'for_printing',ready_for_release:'printed'}[target],eligible=selected.filter(b=>b.dataset.status===required).length,ineligible=selected.length-eligible;if(!selected.length||!confirm(`Confirm production action? Selected: ${selected.length}. Eligible: ${eligible}. Ineligible: ${ineligible}. Resulting status: ${target.replaceAll('_',' ')}.`))e.preventDefault()})})();</script>@endpush